WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (113::BIGINT, 'El mejor profesor del mundo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2026-08-04T00:00:00+00:00'::TIMESTAMPTZ, '36442cdb307d281f321b1eacd96c0668613a8b7755aefd1da32a09e1c7adc12c'::TEXT, ARRAY[1004, 3230]::BIGINT[]),
    (113::BIGINT, 'El curso es muy aburrido, pero este profe hace lo posible por mantener el interés de los estudiantes. Es un amor de persona, de los mejores profes que he tenido en la U, vaya a clases y haga todos los trabajos y el curso se pasa solo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7b72411cb47b04556a6826d413aa59ff3e13bd114d096d7779d2335a9278265d'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'Este señor es de lo mejor la verdad. Se supone que intro es aburrido y sí lo es pero con él se logra soportar. Si pueden matricular con el haganlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-04-23T00:00:00+00:00'::TIMESTAMPTZ, '5070d451b74048d211ce05951e595f2f8faa211b589fb9b36ebd03451697c36f'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El profesor no es claro con las evaluaciones, califica los ensayos muy estrictamente sin ser claro con las métricas de evaluación, no usa TEC Digital casi nada, solo pone documentales en clase. Mejor busque matricular con otro profesor.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'b3d55ac1ee99c3bec772905f6badc58b1ecd28100d0b8d533ad9ef97f18bc715'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'El profe es un pan de dios, lastima que da un curso de mi*rda. Con ir a clases se pasa solo el curso, examenes en la casa y no tiene que estudiar. Al profe lo amo, odio el curso, curso inservible y sin ningun tipo de sentido, ojala lo quiten'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'c7794938896a00efb73ef03efe2c964b27f4767dd0759762e2fbd3723c8dd0fe'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Este Señor es de lo mejor la verdad. La clase en si ya es tediosa no hay de otra, pero el es demasiado basilon y la hace llevadera. Las evaluaciones son medio faciles, solo q si tiene que leer bastante y dedicarle un tiempo. Lleve con él , no se va a arrepentir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'beaebedf130df08f43101690a972c8c209c2149908f3b73482b102cfb0336892'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Estos cursos siempre serán aburridos y tediosos. Y no es secreto que este profe habla bastante. Pero es un buen profe, y lo que habla es interesante. Solo que siempre se le va la conexión xd Haga los trabajos y llegue a las clases, y se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, '5bc3ff4ab7a4999d5bd41adae9a9f994b7b29e66e68e83faba0db10b20b8e050'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'Un profe demasiado tuannis la verdad para una materia tan X. La vara es que el mae hace la clase muy amena y no le va exigir mucho. Lo más son 2 exámenes que hace para lo que hay que leerse unos textos, pero el mae no califica duro. Recomiendo matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '6ff479e630182d4196de24c1c1e2bedf7ee75867259c326a9f1febe00e61def3'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'el profe no hace el curso pesado y además es una persona super amena, con muchos deseos de compartir su conocimiento. La verdad lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-09-11T00:00:00+00:00'::TIMESTAMPTZ, '973c56dabd1c32e9a31aeb6ab826fa7e3ca8b843e1e08d4320aa39ec3ec3b77f'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Es demasiado buena gente, se nota la pasión por su trabajo y por los temas que explica. Permite que sus clases puedan funcionar a través de conversaciones. E incluso, si usted tiene alguna duda sobre temas más allá de la materia le aportará mucha información. Cursar con él es fácil y muy ameno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Pocos exámenes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4cd9e04c09f52e65d86bd3f2705006a78f2cc212110124bf818d19a43d4bec2b'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Muy simpatico y bueno para charlar, sin embargo, por eso mismo las clases son un acertijo, puede hablar de Von Neumman y termina hablando de lo que hacian los abuelos y sus remedios, pongale mucha atención, lea lo que le da y use las presentaciones, ahí esta todo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7f504f8e15eace322624e8c8585c0c3ce737f4cae68c20262b1b527851f8d439'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Muchos dicen que el podria pasar hablando horas hablando de la materia y es totalmente cierto. No es grosero calificando y en realidad es super buena nota y hasta flexible con horas de entrega, pero al chile que preparese para leer y no se duerma en clase ya que si habla mucho, y luego pregunta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, '171c86f740f4ea335ad204bdb1c540600fd63f500608f1aa4db208afff7b10d2'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'El profe deja lecturas bastante largas y de ellas se basan todas las evaluaciones. Usa todo el tiempo de la clase, es buena gente pero no perdona nada. No es el peor, pero hay mejores.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6da73f8638ed3ff19cb87c22fd5c0a9a5f4974ec67938d761d7769ec923cd4f0'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El profe es super buena nota, y la clase con solo ir se pasa, deja muchas lecturas pero no son muy necesarias leerlas por que las ve con una presentación en la clase, los trabajos no son tan largos, la mayoría de los exámenes son reportes de videos relacionados con las lecturas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2023-04-25T00:00:00+00:00'::TIMESTAMPTZ, 'cd03bde36d61cfef3ad499514802a0822a231b3281ede5391355580364eb0d51'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Excelente persona, deja bastantes lecturas, pero no es muy necesario realizarlas, con que ponga atención a las clases, puede hacer los trabajos que deja. Se puede trabajar individual o en parejas. Muy buen profe y se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a7168ab2f2462f3783da2b1bf2d5d09551b4312ab98d68f5f031e8a9895316b0'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El profe es bueno como persona, pero sus clases son súper aburridas y largas, por él podría pasar hablando unas 5 horas. Los trabajos son largos y los ensayos también, aunque no califica duro y es fácil pasar. Pasa lista.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '330868d60490809fab235cfc0f153d43b2768c674fa1d62995c5505e009402d9'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'Le interesa mucho que uno aprenda sobre el curso y no que sea "un curso más de ciencias sociales que hay que llevar para graduarse". Los trabajos son extensos y si no pone mucha atención se vuelven complejos. Es un profe muy atento a sus estudiantes y comprensivo, si usted pide ayuda el la da.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2022-05-27T00:00:00+00:00'::TIMESTAMPTZ, '7e0a5cb35c89e5623894fbc480d07d309e5df6aa338d950a7a265f24115a720f'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'Es la verdad un curso muy equis. Lo unico que quita tiempo son los ensayos, algunas lecturas, y los trabajos en grupo. Pero al final se pasa facil si le fue bien en los ensayos que valen como 40% de la nota, a lo que recuerdo.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, '5032a7169df616886bdf5475cc759ef3f49687100cc95ffdba6ff87b97295140'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'El profe es muy buena nota y muy bueno! A comparación de otros deja mucho más trabajos y los exámenes son más duros y largo ! No es malo si quiere matricular matriculé es muy bueno solo que tome en cuenta qué hay mejores'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, '9358056a89c211a47f7fece035a8fbbcbcf7183668ba60499afd409ed324b312'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Las clases son demasiado aburridas, en las evaluaciones califica con demasiado detalle pero con solo hacer los demás trabajos es suficiente.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '477568bdd1a760b847fc187ba98850039a2cf3d77ea6d4ad0075f94bc62e8578'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Virtual: El profe explica bien y las presentaciones que usa son bastante claras. Deja una lectura cada semana, si las hace pasa fácil. Las evaluaciones son para la casa y deja hacerlas en pareja(recomiendo hacerlas solo, uno se topa con un poco de yeguas)'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1609ddd0a0c0fe77d945d32cde09c3da51ca81fe82cf14543bf4efa8df58ea31'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El curso es muy aburrido, pero se nota que a él le gusta dar la clase, hay que leer bastante pero si usted lleva todo al día y pone atención va a pasar el curso de fijo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '4467aed8cdacbb45e38432a1c9e60f95ea7772110d834ee61911b1bbaeef713d'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Es un profe bastante bueno, con llevar todo al día pasa. Además se aprende bastante en la clase si se pone atención.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '85c9fd3e63750b435e2e218c72065feed2d909180e80cb9c0b1af0eb4a6ac440'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Hay que realizar un proyecto de investigación en grupo, dos ensayos individuales de 5 páginas y como 4 trabajos "cotidianos", estas son las únicas evaluaciones. El profe siempre se atrasa en entregar las evaluaciones revisadas y los promedios finales los entrega el último día.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '8c78d13f1e27bb3568c243a316ab96d9cff17ee672939a3e777af2ac62c9cd5c'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'El curso es demasiado aburrido, pero el profe le pone bastante empeño entonces se hace llevadero. Es muy fácil pasar el curso con él, Basta con llevar al día las lecturas y tomar apuntes ( funcionan bastante para las evaluaciones). Sabe que el curso de un crédito, entonces los trabajos no son largos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '4b751e5fc1f74838d683751aeb524ba43b7d2fbda455ecf54ac355418c7e14be'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El mejor profe para llevar este curso. Muy apasionado con la materia. En sí el curso es muy aburrido, pero él intenta que no sea así. Tiene muy en cuenta que el curso es de un crédito, por lo que los trabajos no son muy largos. Con llevar las lecturas al día, pasa el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Inspirador']::TEXT[], '2020-12-17T00:00:00+00:00'::TIMESTAMPTZ, '39b8eb1dc6efbc800dea157bdb4e2daee44a598fa57514e19dbbcaa3e44e2fb8'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El curso por sí solo requiere mucha lectura y es aburrido, en todo caso el profe es muy claro, evalúa bastante fácil (siempre y cuando ponga de su parte y escriba con lógica). Es muy importante tomar notas, y lo recomiendo al 100% tanto en virtual como presencial'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'c7f0e44dd05170c5a823d03463131f519fbbf0d52fcc803b28dda0d83a6f079b'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El curso es aburrido, sin embargo el profe explica los temas de una forma clara y con gran conocimiento. Sus sus trabajos son sencillos, solo hay que leer bastante cada semana. Los exámenes (si es que se le pueden llamar así), se realizan en casa y son fáciles si realizaste las lecturas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'ef3c9517421e38e02a658ab98f856d9e477c081cce8c30962712fc182c6e2d98'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'En modalidad virtual deja bastante lecturas, hace las clases y las graba sus clases son muy provechosas, y siempre y cuando vea las clases y haga las lecturas que el mismo profe menciona como importantes le va a ir bien en todas las evaluaciones, también deja documentales muy interesantes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'aaed439dbb8983c2337154da31a3dec45717eb7073e2316ef638c02effbd6d4e'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'En general el curso no se presta para mucho, pero el profe lo hace llevadero. Si deja lecturas, generalmente largas y algunas si son aburridas o pesadas. Los trabajos son fáciles, en general todo viene en las lecturas. Casi que me dejó mas escucharlo a el hablar que el curso en sí. Es un buena gente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'f51a985ec6f92151106537002be4f4ccaf31d9e08fa5506c7f93d584d3be8bd2'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Si quiere que un curso de 1 crédito se sienta como de 4 meta con él... las lecturas son largas y aburridas, sus clases son ideales para llegar a dormir, nunca se le entiende lo que quiere en los "exámenes"'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '8fe2d441ccce3587b0017753bfddc6217ad27913e024976236ea19aff602d343'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Es muy bueja gente, la clase puede ser muy aburido, pero el curso en general es muy facil'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '6f156b9272ba77947512b1af30a0c355c27cc906478b86d08f0a1e3781090e22'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'Las clases virtuales las manejo muy bien, tiene clases sincronicas y asincronicas, igual tiene todos los videos grabados, todas las semanas deja leturas pero no son muy largas e igual en clases las explica. Es muy vacilon. Deja 4 trabajos grandes pero todas las respuestas estan en las lecturas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'df42da3924ee4be4f90b01f8234ddb34ca41592c7763b5369e8c353dadbf8da8'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El curso es aburrido, pero el profesor es buena gente, es muy fácil pasar con él, casi todos los trabajos y exámenes se hacen en la casa y en grupos, él se interesa mucho en la clase, tome apunte o tome fotos de las presentaciones, las preguntas suelen ser de ahí.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-12-11T00:00:00+00:00'::TIMESTAMPTZ, '754cea35acf5b3e0e880e00f788b492d836249178c2cbeb59575a090bdeee47d'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Amilkar es un profesor excelente, además es muy buena persona y se nota que le interesa mucho lo que enseña, entonces transmite ese interés. El curso es fácil, si usted pone atención, toma notas de las presentaciones del profe y hace las lecturas, con eso ya puede hacer los trabajos y exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-07-09T00:00:00+00:00'::TIMESTAMPTZ, '6d0ae1ee0d74715abe48ea4463b8a7e66d257260af90f260faf540e0b7ee195b'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El curso es relativamente fácil, solo que hay que leer bastante.Los exámenes se hacen en la casa y los prefiere en grupos, pero se tienen que contestar las preguntas en forma amplia y tomar apuntes de lo que dice en clase para añadirlo. Se hacen como 3 reportes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'f923c00e399a3249b5529254febdb486df47e8e0a192583ccadfad2f5e7ff54a'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El mae convierte un curso fácil con muchos otros profes en un curso donde cada semana hay que estar leyendo como si uno al igual que él fuera sociólogo, las evaluaciones son aburridas y siempre le escribe a uno que le faltó desarrollar más.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'bd69e3a4afe11887bbebaeb5fb476e1d65124ca1330eb52b20c71b7bd6537878'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'No hace exámenez, quizes y deja como 6 tareas super accesibles, le encanta que lean completos los libros. Tiene un humor que tal vez solo el entiende pero es demasiado bueno, y uno se gana un amigo por el resto de la carrera, buenísimo profe.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '8373c377753aaf34eae6350c60ed22e90ff6c06dc8ef5eddfde872bffee474b5'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'La materia de introducción tiende a ser tediosa, pero aún así el profe intenta presentarla de forma amena para los estudiantes. Asigna lecturas semanales, que son de gran importancia para los trabajos que deja al final de cada unidad. Súper recomendado!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '84e7f65b9771a5faebdc1abb1610f221e8f4215eb954d38fa1839c358cb07bfa'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Muy bueno el profesor, intenta hacer la clase lo más entretenida posible aunque la materia no ayuda mucho. No hace exámenes, son trabajos en grupo y sencillos'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '10d9598d37e4faef67fc43ebe0e70b408c637549288a23e1f683a1e183a2e5d5'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '7c86e65def925b0540915001b89785ba142e5ebfe2f7201b811acb6446c21d07'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Es bueno, pero el curso es aburrido'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2019-03-06T00:00:00+00:00'::TIMESTAMPTZ, 'f6a4f682e6859601c535ef3fbb21e1a0799e42a8cf60338b7f3c4238ec1d1482'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Es un profesor excelente y a mi parecer hace que las clases sean súper interesantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'dba404fc87afe06a445a1c1c8bf439799e79e4e4ba9e26f3f754fb2b64135f8d'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Las clases son aburridas y de asistencia obligatoria, pero en general no hay que participar mucho, "hay que leer mucho" pero tampoco es tan estricto al respecto. Es bastante flexible con los trabajos y no califica duro.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'fedc905e0930823c5e79cbe59844b36862aa2023a5d7249a64547b3670584b0d'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'Dolorosamente aburrido pero se pasa el curso desde que se matricula.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '44a888a4750f6a1d5568222805f01e30236ee686c909cab68f79c747c55c1e31'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'El profe es muy aburrido, pero se aprende bastante si uno se mete en el tema y le pone atención en la clase. Mi grupo era bastante participativo y eso evitaba que me durmiera constantemente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '6f3930bc22933c50ac2b46ba11d30aa9db574d1ce94408adca197ae7f6191a87'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'RESUMEN: ÉL HABLA, USTED... (ESCUCHA Y APRENDE O SE DUERME), él es muy amable, exámenes fáciles, solo sea respetuoso ponga atención y se prende mucho y se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd545e251b0cbb68f50e51860377da0c06664e5b3804c2b5c1d0792f9ac1cbda6'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El profe es buena nota, evaluaciones para la casa en lugar de exámenes. Se pasa fácil con él.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c80493b9d6bbabd64fe4047cefe9169c873d56f39b8e8ae163a78d942c068c4c'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Bastante bien, deja los exámenes para la casa y en parejas o tríos y un ensayo por cada documental (son 3). Explica claro y ayuda bastante. Deja lecturas cada semana. La clase es MUY aburrida, pero el curso con casi cualquier profe va a ser así'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '72d4053496286b1e96cb992690c8667dd2e70c5f5aae760ed0e2138e276f8599'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'El mae es muy aburrido, deja lecturas de 30 paginas cada semana, es deficiente con el uso del TEC Digital. Pide que haga resúmenes de documentales y deja cuestionarios en grupo en vez de exámenes . Califica suave, si le pone con esas cosas, puede hacer las mías de ver pelis en clases, jugar, etc.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '842e9dcecf803cf3febb8694d2d7ff357eabbb34d6bdf70e897cfc4fec62afc7'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Muy buen profe, deja los exámenes para la casa, explica muy bien y se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'cd4530edb44eb2a98084db0d1b6df77539e8f127d0a64348c653f56c2bca8954'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Es fácil pasar con él'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'd4a318323ecdce53529b934c8939f8551de24ec2e94abc1cb86dbed51fc99908'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Muy buen profesor. Sabe bastante. Su explicación no es muy clara, pero si se lee las lecturas se entiende todo. Califica suave. En vez de parciales hace evaluaciones para la casa. Aclara dudas con gusto, hace buenos ejemplos. Es aburrido pero la clase es así con cualquier profe.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a326f29727cd4f3417c93608653d04a451d97c2b49f7832735fcc47c5ac616c5'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Se toma muy en serio eso de "intro al bostezo", pero de todas maneras la materia no es la más entretenida, siempre está feliz y los trabajos no los califica rudo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'f628ba9bdb308dcb74573d24d3d625aef2216e18d276b7b191d744007e484cf3'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Hace exámenes para la casa, reportes de vídeos que se ven en clases (se encuentran en Internet) y las lecturas algunas son extensas. Buen profesor, se ve que tiene gusto por lo que hace.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'db48028cf1c850d928489161bb649b40255966e63f3375f3b115da96d4dedd6e'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Definitivamente sabe de lo que habla, ilustra toditico con ejemplos y a leguas se ve que le gusta dar clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'f2eecc39a892aab686258808dd9868322cc9cb8035eb319a9f36dd321187afa4'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Las clases son muy aburridas, pero porque el curso se presta a serlo. Él sabe bastante y se nota que le gusta lo que estudió. Deja lecturas sumamente enormes, pero mientras uno comente algo de la lectura en clase, está bien. Los trabajos y tareas son fáciles y no demanda mucho tiempo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'c9316166909429346ec78523a96b499e5118e0a78f9d4a5d7ff1cc0a51e6091f'::TEXT, ARRAY[1004]::BIGINT[]),
    (113::BIGINT, 'Son clases son muy aburridas no porque el las haga asi sino que la materia no se presta para hacerla interesante. Es una excelente persona que le gusta lo que hace y sus trabajos toman tiempo pero deja muy pocos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '36f67e8975457164f59d604d32cce9623e1a09a09d40c936a80531b8f122a0f9'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '72ff4f3fd83f374e9f37f91abc39c3945d7350e0c9f3cd059158562af220cf2f'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Buen profe, algo aburrido pero se esfuerza para que todos entiendan y la clase no sea tan aburrida.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-20T00:00:00+00:00'::TIMESTAMPTZ, '63c76683ae7cf2ab2bad0de10db4e6a02ecdf4325a89923029bdec2e484f3afa'::TEXT, ARRAY[628]::BIGINT[]),
    (113::BIGINT, 'las clases son un poco aburridas pero es buen profe, los trabajos son largos pero por lo general fáciles de hacer y le ayuda a los estudiantes que muestran interes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '668656aaa052118bb4570f22d0a42d88c7e5db34ed77471b67c560d7a81e38da'::TEXT, ARRAY[559]::BIGINT[]),
    (113::BIGINT, 'Excelente profesional y persona. Ama Lo que hace y cualquier aporte le parece excelente. Ayuda con los trabajos a los estudiantes. Cuesta mucho sacar mala nota con él. Es demasiado feliz.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-12T00:00:00+00:00'::TIMESTAMPTZ, '2f5dbb41051bb6658cacf710a04c92f763c080ee03c819db30ca1cb38e962caa'::TEXT, ARRAY[559]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
